<?php
declare(strict_types=1);
namespace OCA\AdPlaner\Service;
use InvalidArgumentException;use OCA\AdPlaner\Repository\TemporaryAdminAccessRepositoryInterface;use OCP\AppFramework\Utility\ITimeFactory;use OCP\IGroupManager;use OCP\IUserSession;use Psr\Log\LoggerInterface;use Throwable;
final class TemporaryAdminAccessService implements TemporaryAdminAccessChecker {public const MAX_DURATION_MINUTES=1440;public function __construct(private IUserSession $session,private IGroupManager $groups,private TemporaryAdminAccessRepositoryInterface $repository,private ITimeFactory $clock,private LoggerInterface $logger){}public function activate(string $targetUid,int $durationMinutes):array{$actor=$this->requireAdmin();$targetUid=trim($targetUid);if($targetUid===''||!$this->groups->isAdmin($targetUid))throw new InvalidArgumentException('Zielkonto ist keine aktuelle Nextcloud-Administration.');if($durationMinutes<1||$durationMinutes>self::MAX_DURATION_MINUTES)throw new InvalidArgumentException('Die Freigabedauer muss zwischen 1 und 1440 Minuten liegen.');$start=$this->clock->now();$grant=$this->repository->replaceActive($targetUid,$actor,$start,$start->modify('+'.$durationMinutes.' minutes'));$this->logger->info('Temporary app admin access granted.',['grant_id'=>$grant['id']??null]);return $grant;}public function revoke(string $targetUid):bool{$revoked=$this->repository->revokeActive(trim($targetUid),$this->requireAdmin(),$this->clock->now());if($revoked)$this->logger->info('Temporary app admin access revoked.');return $revoked;}public function hasActiveGrant(string $uid):bool{$uid=trim($uid);if($uid===''||!$this->groups->isAdmin($uid))return false;try{return $this->repository->activeFor($uid,$this->clock->now())!==null;}catch(Throwable){$this->logger->error('Temporary app admin access check failed.');return false;}}public function state():array{$this->requireAdmin();return ['maxDurationMinutes'=>self::MAX_DURATION_MINUTES,'history'=>$this->repository->history()];}private function requireAdmin():string{$uid=$this->session->getUser()?->getUID()??'';if($uid===''||!$this->groups->isAdmin($uid))throw new TemporaryAdminAccessDeniedException();return $uid;}}
